MODES.boat={name:'游船',color:'#4f8194',dash:'8 4',icon:'船'};
MODES.taxi={name:'出租车',color:'#9b723c',dash:'8 5',icon:'车'};
if(typeof ACCESS_HOURS!=='undefined')for(const p of Object.values(JOURNEY_MODEL.places)){if(p.hours)ACCESS_HOURS[p.id]=p.hours;}
